{"content": "1|// Enforces the size budget of the shipped game (index.html + src/**).
2|// Usage: node tools/size-check.mjs     Exit code 1 when over budget.
3|import { readdirSync, readFileSync, statSync } from 'node:fs';
4|import { join, relative, resolve } from 'node:path';
5|import { gzipSync } from 'node:zlib';
6|import { fileURLToPath } from 'node:url';
7|
8|// MVP uses ~52 KB raw / ~19 KB gzip. The headroom is for candidates' features.
9|export const BUDGET = { raw: 96 * 1024, gzip: 32 * 1024 };
10|
11|const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
12|const walk = (dir) => readdirSync(dir).flatMap((f) => {
13|  const p = join(dir, f);
14|  return statSync(p).isDirectory() ? walk(p) : [p];
15|});
16|
17|const files = [join(ROOT, 'index.html'), ...walk(join(ROOT, 'src'))];
18|const all = Buffer.concat(files.map((f) => readFileSync(f)));
19|const raw = all.length, gzip = gzipSync(all, { level: 9 }).length;
20|
21|const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
22|for (const f of files) console.log(`${kb(statSync(f).size).padStart(9)}  ${relative(ROOT, f).replaceAll('\\', '/')}`);
23|console.log('-'.repeat(40));
24|console.log(`${kb(raw).padStart(9)}  total raw   (budget ${kb(BUDGET.raw)})`);
25|console.log(`${kb(gzip).padStart(9)}  total gzip  (budget ${kb(BUDGET.gzip)})`);
26|
27|if (raw > BUDGET.raw || gzip > BUDGET.gzip) {
28|  console.error('\nSize budget exceeded. Generate it, don\'t ship it.');
29|  process.exit(1);
30|}
31|console.log('\nWithin budget.');", "total_lines": 31, "file_size": 1417, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * The only shader pair in the game. All surface detail (windows, water,
3| * asphalt grain, soft shadow) is computed here from world position, so the
4| * game ships zero texture bytes.
5| */
6|
7|export const VERTEX_SHADER = `#version 300 es
8|layout(location = 0) in vec3 aPos;
9|layout(location = 1) in vec3 aNormal;
10|layout(location = 2) in vec3 aColor;
11|layout(location = 3) in float aMat;
12|uniform mat4 uProj, uView, uModel;
13|out vec3 vPos;
14|out vec3 vNormal;
15|out vec3 vColor;
16|flat out int vMat;
17|void main() {
18|  vec4 w = uModel * vec4(aPos, 1.0);
19|  vPos = w.xyz;
20|  vNormal = mat3(uModel) * aNormal;
21|  vColor = aColor;
22|  vMat = int(aMat + 0.5);
23|  gl_Position = uProj * uView * w;
24|}`;
25|
26|export const FRAGMENT_SHADER = `#version 300 es
27|precision highp float;
28|in vec3 vPos;
29|in vec3 vNormal;
30|in vec3 vColor;
31|flat in int vMat;
32|uniform vec3 uEye, uSunDir, uFogColor;
33|uniform float uFogDensity, uTime;
34|out vec4 outColor;
35|
36|float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
37|
38|// Procedural facade. g = (window column width, floor height) in metres.
39|vec3 facade(vec3 base, vec3 n, vec2 g, bool platte) {
40|  vec2 p = vec2(dot(vPos.xz, vec2(n.z, -n.x)), vPos.y - 0.15);
41|  vec2 cell = floor(p / g), f = fract(p / g);
42|  float r = hash(cell);
43|  bool shop = !platte && cell.y < 1.0;
44|  vec2 lo = shop ? vec2(0.08, 0.06) : vec2(0.3, 0.28);
45|  vec2 hi = shop ? vec2(0.92, 0.75) : vec2(0.7, 0.8);
46|  float win = step(lo.x, f.x) * step(f.x, hi.x) * step(lo.y, f.y) * step(f.y, hi.y);
47|  vec3 glass = mix(vec3(0.1, 0.13, 0.17), vec3(0.42, 0.5, 0.58), r * r);
48|  if (shop) glass = r > 0.65 ? vec3(0.85, 0.72, 0.45) : vec3(0.16, 0.18, 0.2);
49|  vec3 c = base;
50|  if (platte && (f.x < 0.03 || f.y < 0.05)) c *= 0.8;         // panel joints
51|  if (!platte && f.y > 0.86 && f.y < 0.93) c *= 0.88;         // cornice band
52|  return mix(c, glass, win);
53|}
54|
55|void main() {
56|  vec3 n = normalize(vNormal);
57|  vec3 c = vColor;
58|  float alpha = 1.0, spec = 0.0;
59|  bool wall = abs(n.y) < 0.5;
60|
61|  if (vMat == 1 && wall) c = facade(c, n, vec2(3.0, 3.6), false);
62|  else if (vMat == 2 && wall) c = facade(c, n, vec2(3.2, 2.8), true);
63|  else if (vMat == 3) {
64|    float w = sin(vPos.x * 0.35 + uTime * 1.3) + sin(vPos.z * 0.6 - uTime * 0.9 + vPos.x * 0.2);
65|    n = normalize(vec3(w * 0.06, 1.0, w * 0.04));
66|    spec = 0.6;
67|  }
68|  else if (vMat == 4) c *= 0.96 + 0.06 * hash(floor(vPos.xz * 4.0));
69|  else if (vMat == 5) spec = 0.35;
70|  else if (vMat == 6) {
71|    alpha = 0.55 * (1.0 - smoothstep(0.5, 1.0, length(vColor.xy)));
72|    c = vec3(0.0);
73|  }
74|  if (wall && vMat < 3) c *= mix(0.72, 1.0, clamp(vPos.y / 5.0, 0.0, 1.0)); // fake ambient occlusion
75|
76|  vec3 v = normalize(uEye - vPos);
77|  float diff = max(dot(n, uSunDir), 0.0);
78|  vec3 sky = mix(vec3(0.32, 0.3, 0.28), vec3(0.62, 0.7, 0.82), 0.5 + 0.5 * n.y);
79|  vec3 col = c * (vec3(1.0, 0.95, 0.86) * diff * 0.8 + sky * 0.55);
80|  col += spec * pow(max(dot(n, normalize(uSunDir + v)), 0.0), 48.0);
81|  float d = length(uEye - vPos) * uFogDensity;
82|  col = mix(col, uFogColor, 1.0 - exp(-d * d));
83|  outColor = vec4(col, alpha);
84|}`;", "total_lines": 84, "file_size": 3041, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Arcade car physics using a kinematic bicycle model.
3| * PURE: no DOM, no WebGL — runs in Node for tests.
4| *
5| * Car state: position (x, z), heading (rad, 0 = facing +Z / south), speed (m/s,
6| * negative when reversing), steer (front wheel angle in rad, + = left).
7| */
8|import { approach } from '../core/math.js';
9|
10|/** Tuning for a typical German taxi (mid-size saloon). */
11|export const TAXI = {
12|  wheelBase: 2.9, // m between axles
13|  trackWidth: 1.64, // m between left and right wheels
14|  wheelRadius: 0.34,
15|  maxSteer: 0.6, // rad at standstill
16|  steerRate: 2.5, // rad/s the steering wheel can turn
17|  maxLateralAccel: 14, // m/s² — arcade grip (a real saloon manages ~9)
18|  engineAccel: 6.5, // m/s² at standstill, fades out towards maxSpeed
19|  brakeDecel: 14,
20|  reverseAccel: 4,
21|  maxSpeed: 36, // m/s ≈ 130 km/h
22|  maxReverse: 8,
23|  rollingResistance: 0.4, // m/s²
24|  airDrag: 0.0022, // m/s² per (m/s)²
25|  handbrakeDecel: 9,
26|  collisionRadius: 0.95, // the body is approximated by two circles
27|  collisionOffset: 1.45, // their distance from the centre along the car axis
28|  restitution: 0.25, // bounce on impact
29|};
30|
31|export function createCar({ x, z, heading }) {
32|  return { x, z, heading, speed: 0, steer: 0, wheelSpin: 0 };
33|}
34|
35|/**
36| * Advances the car by dt seconds.
37| * input = { throttle: 0..1, brake: 0..1, steer: -1..1 (+ = left), handbrake: bool }
38| */
39|export function stepCar(car, input, spec, dt) {
40|  // Grip-limited steering: never ask the tyres for more than maxLateralAccel (v²/L·tan δ ≤ a).
41|  const steerLimit = Math.min(spec.maxSteer, Math.atan((spec.maxLateralAccel * spec.wheelBase) / (car.speed * car.speed + 1e-6)));
42|  car.steer = approach(car.steer, input.steer * steerLimit, spec.steerRate * dt);
43|
44|  // Throttle accelerates forward (or brakes while rolling backwards), brake does the opposite.
45|  const v = car.speed;
46|  let accel = 0;
47|  if (input.throttle) accel += v < -0.5 ? spec.brakeDecel : input.throttle * spec.engineAccel * (1 - Math.max(v, 0) / spec.maxSpeed);
48|  if (input.brake) accel -= v > 0.5 ? spec.brakeDecel : input.brake * spec.reverseAccel * (1 + Math.min(v, 0) / spec.maxReverse);
49|  car.speed += accel * dt;
50|
51|  // Resistances oppose motion but never reverse it on their own.
52|  let drag = spec.rollingResistance + spec.airDrag * car.speed * car.speed;
53|  if (input.handbrake) drag += spec.handbrakeDecel;
54|  car.speed -= Math.sign(car.speed) * Math.min(Math.abs(car.speed), drag * dt);
55|
56|  // Bicycle model: yaw rate follows from speed, wheel base and steering angle.
57|  const yawRate = (car.speed / spec.wheelBase) * Math.tan(car.steer) * (input.handbrake ? 1.4 : 1);
58|  car.heading += yawRate * dt;
59|  car.x += Math.sin(car.heading) * car.speed * dt;
60|  car.z += Math.cos(car.heading) * car.speed * dt;
61|  car.wheelSpin = (car.wheelSpin + (car.speed / spec.wheelRadius) * dt) % (Math.PI * 2);
62|  return car;
63|}", "total_lines": 63, "file_size": 2853, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

