{"content": "1|/**
2| * Keyboard input. Uses KeyboardEvent.code (physical keys), so WASD works on
3| * QWERTY and QWERTZ layouts alike.
4| */
5|const CAPTURED = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space']);
6|
7|export class Keyboard {
8|  constructor(target = window) {
9|    this.down = new Set();
10|    this.pressed = new Set();
11|    target.addEventListener('keydown', (e) => {
12|      if (CAPTURED.has(e.code)) e.preventDefault(); // no page scrolling while driving
13|      if (!e.repeat) this.pressed.add(e.code);
14|      this.down.add(e.code);
15|    });
16|    target.addEventListener('keyup', (e) => this.down.delete(e.code));
17|    target.addEventListener('blur', () => this.down.clear());
18|  }
19|
20|  any(...codes) {
21|    return codes.some((c) => this.down.has(c));
22|  }
23|
24|  /** True exactly once per key press (edge-triggered). */
25|  consume(code) {
26|    return this.pressed.delete(code);
27|  }
28|
29|  /** Call at the end of every frame so unconsumed presses do not pile up. */
30|  endFrame() {
31|    this.pressed.clear();
32|  }
33|
34|  /** Maps keys to the input shape expected by stepCar(). */
35|  driving() {
36|    return {
37|      throttle: this.any('KeyW', 'ArrowUp') ? 1 : 0,
38|      brake: this.any('KeyS', 'ArrowDown') ? 1 : 0,
39|      steer: (this.any('KeyA', 'ArrowLeft') ? 1 : 0) - (this.any('KeyD', 'ArrowRight') ? 1 : 0),
40|      handbrake: this.any('Space'),
41|    };
42|  }
