9|/**
10| * Pushes a circle out of all colliders it overlaps.
11| * Returns null when there is no contact, else { dx, dz, nx, nz } (total push and contact normal).
12| */
13|export function pushOut(x, z, r, colliders) {
14|  const ox = x, oz = z;
15|  let nx = 0, nz = 0, hit = false;
16|  for (const c of colliders) {
17|    let px, pz, depth;
18|    if (c.type === 'box') {
19|      if (x < c.x0 - r || x > c.x1 + r || z < c.z0 - r || z > c.z1 + r) continue;
20|      const qx = Math.min(Math.max(x, c.x0), c.x1), qz = Math.min(Math.max(z, c.z0), c.z1);
21|      const dx = x - qx, dz = z - qz, d = Math.hypot(dx, dz);
22|      if (d >= r) continue;
23|      if (d > 1e-6) {
24|        [px, pz, depth] = [dx / d, dz / d, r - d];
25|      } else {
26|        // Centre is inside the box: leave through the nearest side.
27|        const sides = [[x - c.x0, -1, 0], [c.x1 - x, 1, 0], [z - c.z0, 0, -1], [c.z1 - z, 0, 1]];
28|        const [pen, sx, sz] = sides.reduce((a, b) => (b[0] < a[0] ? b : a));
29|        [px, pz, depth] = [sx, sz, pen + r];
30|      }
